# Let's implement a simple version of the helper functions to understand the patterns
inputs = ['ukfb', 'wwi', 'iu', 'cfygk', 'kv']
outputs = ['ukfb', 'ddi', 'iu', 'cfyj', 'kydk']

# First, let's find the changed pairs
changed_pairs = []
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        changed_pairs.append((i, inp, out))

print("Changed pairs:")
for idx, inp, out in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{out}'")

# Now let's examine each change more carefully
print("\nDetailed analysis:")
for idx, inp, out in changed_pairs:
    print(f"\n{idx}: '{inp}' -> '{out}'")

    # Find minimal edit for each position
    if len(inp) == len(out):
        # Same length - character substitution
        for i, (ch_in, ch_out) in enumerate(zip(inp, out)):
            if ch_in != ch_out:
                print(f"  Position {i}: '{ch_in}' -> '{ch_out}'")
    elif len(inp) > len(out):
        # Deletion
        print(f"  Deletion detected (length {len(inp)} -> {len(out)})")
    else:
        # Insertion
        print(f"  Insertion detected (length {len(inp)} -> {len(out)})")

